#!/usr/bin/env node
// build-runner-bundle.mjs
//
// Stages a self-contained ARchetipo CLI bundle for a foreign platform — the one
// an ARcipelago runner container runs on — without publishing anything and
// without touching the tracked files under npm/.
//
// The bundle is deliberately *not* an npm install: a container that only has to
// invoke `archetipo` does not need the Node shim nor the optional-dependency
// dance. It needs the native binary, the packaged skills and the runtime
// assets, plus ARCHETIPO_DATA_DIR pointing at the bundle root — which is
// exactly what the shim sets before spawning the binary
// (npm/archetipo/bin/archetipo.js).
//
// Usage:
//   node scripts/build-runner-bundle.mjs [--platform linux-arm64] [--out <dir>]
//
// Output layout (default .dev/runner-bundle/):
//   bin/archetipo        → Go binary cross-compiled for the target platform
//   skills/              → packaged ARchetipo skills
//   runtime/             → config.yaml + shared-runtime.md
//
// Mount it into the runner and export:
//   ARCHETIPO_DATA_DIR=<bundle>   PATH=<bundle>/bin:$PATH

import fs from "node:fs/promises";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, "..");

const supported = new Set([
	"darwin-arm64", "darwin-x64",
	"linux-arm64", "linux-x64",
	"win32-arm64", "win32-x64",
]);

function parseArgs(argv) {
	const args = {
		platform: "linux-arm64",
		out: null,
		project: null,
		slug: null,
		services: ["runner-1", "runner-2"],
		compose: undefined,
	};
	for (let i = 0; i < argv.length; i++) {
		const flag = argv[i];
		if (flag === "--platform" || flag === "-p") args.platform = argv[++i];
		else if (flag === "--out" || flag === "-o") args.out = argv[++i];
		else if (flag === "--project") args.project = argv[++i];
		else if (flag === "--slug") args.slug = argv[++i];
		else if (flag === "--services") args.services = argv[++i].split(",").map((s) => s.trim()).filter(Boolean);
		else if (flag === "--compose") {
			// The path is optional: `--compose` alone takes the default location.
			const next = argv[i + 1];
			args.compose = next && !next.startsWith("--") ? argv[++i] : path.join(repoRoot, ".dev", "docker-compose.archetipo.yml");
		} else {
			console.error(`unknown argument: ${flag}`);
			process.exit(1);
		}
	}
	if (!supported.has(args.platform)) {
		console.error(`unsupported platform ${args.platform}; expected one of ${[...supported].join(", ")}`);
		process.exit(1);
	}
	args.out ??= path.join(repoRoot, ".dev", "runner-bundle");
	if (args.compose && !args.project) {
		console.error("--compose needs --project <dir>: the overlay mounts that checkout as the runner's working directory");
		process.exit(1);
	}
	if (args.project) {
		args.project = path.resolve(args.project);
		args.slug ??= path.basename(args.project);
	}
	return args;
}

// Renders the dev-stack overlay with both paths already resolved.
//
// The paths are baked in rather than left as ${VARIABLES} because Docker
// silently *creates* a missing bind source as a root-owned empty directory: a
// typo in an exported path does not fail at startup, it surfaces much later
// inside the container as `archetipo: not found`. Resolving here means a wrong
// path fails now, on this machine, naming the directory that is not there.
//
// The capability tag is the other half of the same idea. The workspace on the
// hub says `--requires project:<slug>`; this says which runners carry it. A
// machine without the checkout is then refused at once instead of accepting
// work it cannot do.
function renderCompose({ project, slug, services, bundleDir }) {
	const body = services
		.map((name) => `  ${name}:
    environment:
      ARCHETIPO_DATA_DIR: /opt/archetipo
      ARCIPELAGO_CAPABILITIES: "project:${slug}"
      ARCIPELAGO_MAX_SESSIONS: "8"
      PATH: /opt/archetipo/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
    volumes:
      - ${project}:/workspace
      - ${bundleDir}:/opt/archetipo:ro`)
		.join("\n");
	return `# Generated by scripts/build-runner-bundle.mjs — do not edit; re-run to refresh.
#
# The base dev stack gives every runner an empty named volume as its working
# directory, which is right for a general-purpose fleet and wrong for ARchetipo:
# the prompt ARchetipo sends states that the working directory *is* a checkout
# of the project, with the CLI and the skills already installed. This makes that
# true, and declares it to the hub as a capability so a runner without it is
# never given the work.
#
# The project is mounted read-write on purpose: a remote agent that plans or
# implements a spec persists through the connector, and those writes have to
# land in the same working copy the local \`archetipo view\` reads.
name: arcipelago-dev

services:
${body}
`;
}

function run(cmd, cmdArgs, opts = {}) {
	const result = spawnSync(cmd, cmdArgs, { cwd: repoRoot, encoding: "utf8", ...opts });
	if (result.error) {
		console.error(`${cmd} failed to start: ${result.error.message}`);
		process.exit(1);
	}
	if (result.status !== 0) {
		if (result.stderr) process.stderr.write(result.stderr);
		console.error(`${cmd} ${cmdArgs.join(" ")} exited with status ${result.status}.`);
		process.exit(1);
	}
	return result;
}

async function exists(p) {
	try { await fs.access(p); return true; } catch { return false; }
}

// The version string is the same one install:dev stamps, so a bundle and a
// global dev install built from the same commit report the same version and a
// mismatch between host and runner is visible in `archetipo version`.
function devVersion() {
	const sha = run("git", ["rev-parse", "--short", "HEAD"]).stdout.trim();
	const dirty = spawnSync("git", ["diff-index", "--quiet", "HEAD", "--"], { cwd: repoRoot }).status !== 0;
	return `0.0.0-dev.g${sha}${dirty ? ".dirty" : ""}`;
}

const args = parseArgs(process.argv.slice(2));
const [goos, goarch] = args.platform.split("-");
const version = devVersion();
const outDir = path.resolve(args.out);

// Checked before anything is built: a missing checkout is the one mistake that
// would otherwise be discovered inside a container, minutes later, as a command
// that is not found.
if (args.project && !(await exists(args.project))) {
	console.error(`--project ${args.project} does not exist`);
	process.exit(1);
}

await fs.rm(outDir, { recursive: true, force: true });
await fs.mkdir(path.join(outDir, "bin"), { recursive: true });

console.log(`Building ${args.platform} binary @ ${version}`);
run(
	"go",
	[
		"build",
		"-o", path.join(outDir, "bin", goos === "win32" ? "archetipo.exe" : "archetipo"),
		"-ldflags", `-s -w -X github.com/techreloaded-ar/ARchetipo/cli/internal/version.Version=${version}`,
		"./cmd/archetipo",
	],
	{
		cwd: path.join(repoRoot, "cli"),
		stdio: "inherit",
		// win32 is npm's spelling, not Go's.
		env: { ...process.env, GOOS: goos === "win32" ? "windows" : goos, GOARCH: goarch, CGO_ENABLED: "0" },
	},
);

await fs.cp(path.join(repoRoot, "skills"), path.join(outDir, "skills"), { recursive: true });
await fs.mkdir(path.join(outDir, "runtime"), { recursive: true });
for (const name of ["config.yaml", "shared-runtime.md"]) {
	const src = path.join(repoRoot, ".archetipo", name);
	if (await exists(src)) await fs.copyFile(src, path.join(outDir, "runtime", name));
}

console.log(`✓ ${path.relative(repoRoot, outDir)}/ (${args.platform}, ${version})`);

if (!args.compose) {
	console.log("  mount it and export ARCHETIPO_DATA_DIR=<mount> and PATH=<mount>/bin:$PATH");
	console.log("  or pass --project <checkout> --compose to have the overlay written for you");
	process.exit(0);
}

const composePath = path.resolve(args.compose);
await fs.mkdir(path.dirname(composePath), { recursive: true });
await fs.writeFile(
	composePath,
	renderCompose({ project: args.project, slug: args.slug, services: args.services, bundleDir: outDir }),
);
console.log(`✓ ${path.relative(repoRoot, composePath)} (${args.services.join(", ")} → ${args.project})`);
console.log("\nBring the fleet up:\n");
console.log(`  docker compose -f provisioning/docker-compose.dev.yml -f ${composePath} up -d\n`);
// Both halves of the same statement, so neither is left implied: the runners
// now advertise the tag, and the workspace has to be the thing that asks for it.
console.log("Then tell the hub what this workspace needs:\n");
console.log(`  arcipelago workspaces update <workspace> --cwd /workspace --requires project:${args.slug} --model <provider/model>\n`);
console.log("And in the project:\n");
console.log("  archetipo execution setup --url <hub>");
